UPDATE m_housework_template
SET
    name_ja            = #{item.nameJa}
  , name_en            = #{item.nameEn}
  , name_es            = #{item.nameEs}
  , description_ja     = #{item.descriptionJa}
  , description_en     = #{item.descriptionEn}
  , description_es     = #{item.descriptionEs}
  , recommendation_ja  = #{item.recommendationJa}
  , recommendation_en  = #{item.recommendationEn}
  , recommendation_es  = #{item.recommendationEs}
  , category           = #{item.category}
  , recurrence_type    = #{item.recurrenceType}
  , weekly_days        = #{item.weeklyDays}
  , day_of_month       = #{item.dayOfMonth}
  , nth_week           = #{item.nthWeek}
  , weekday            = #{item.weekday}
  , update_user_id     = #{userId}
  , update_program     = #{program}
WHERE
    housework_template_id = #{item.houseworkTemplateId}
